/**计算从1累加到n的值，n为传入的参数值*/ 
DROP FUNCTION IF EXISTS func;
CREATE FUNCTION func (n INT) RETURNS INT DETERMINISTIC

BEGIN
  DECLARE sum INT DEFAULT 0;

  WHILE n > 0 DO
    SET sum := sum + n;
    SET n := n - 1;
  END WHILE;

  RETURN sum;
END;

SELECT func(100);
